import{_ as e,o as a,c as t,a6 as s}from"./chunks/framework.4tsfTCyC.js";const u=JSON.parse('{"title":"Working with Figures","description":"","frontmatter":{},"headers":[],"relativePath":"guide/working-with-figures.md","filePath":"guide/working-with-figures.md"}'),o={name:"guide/working-with-figures.md"};function r(n,i,l,d,c,p){return a(),t("div",null,[...i[0]||(i[0]=[s('<h1 id="working-with-figures" tabindex="-1">Working with Figures <a class="header-anchor" href="#working-with-figures" aria-label="Permalink to &quot;Working with Figures&quot;">​</a></h1><p>TeXRA allows AI agents to analyze, reference, and generate figures within your documents.</p><h2 id="quick-task-add-a-figure-caption" tabindex="-1">Quick Task: Add a Figure Caption <a class="header-anchor" href="#quick-task-add-a-figure-caption" aria-label="Permalink to &quot;Quick Task: Add a Figure Caption&quot;">​</a></h2><ol><li>Select the <code>polish</code> agent from the dropdown</li><li>Choose a vision-capable model (e.g., <code>gemini25p</code>, <code>gpt4o</code>)</li><li>Select your figure in the <strong>Media</strong> section</li><li>Enter instruction: &quot;Write a detailed caption for this figure&quot;</li><li>Click Execute</li></ol><h2 id="the-media-section" tabindex="-1">The Media Section <a class="header-anchor" href="#the-media-section" aria-label="Permalink to &quot;The Media Section&quot;">​</a></h2><p>The main TeXRA panel includes a &quot;Media&quot; section for managing figure files:</p><ul><li><strong>Dropdown</strong>: Select a primary media file</li><li><strong>Multiple Toggle</strong>: Expand to select multiple files</li><li><strong>Auto Extract Dropdown</strong>: Configure automatic figure extraction</li></ul><h2 id="supported-file-types" tabindex="-1">Supported File Types <a class="header-anchor" href="#supported-file-types" aria-label="Permalink to &quot;Supported File Types&quot;">​</a></h2><p>Configurable via <code>texra.files.included.mediaExtensions</code>:</p><ul><li><strong>Images</strong>: <code>.png</code>, <code>.jpeg</code>, <code>.jpg</code>, <code>.gif</code>, <code>.heic</code>, <code>.heif</code>, <code>.webp</code></li><li><strong>Documents</strong>: <code>.pdf</code> (native or converted to images)</li><li><strong>Audio</strong> (experimental): <code>.wav</code>, <code>.m4a</code>, <code>.mp3</code>, <code>.aiff</code>, <code>.aac</code>, <code>.ogg</code>, <code>.flac</code></li></ul><p>PDFs are processed natively when supported (Anthropic/Gemini/OpenAI). Otherwise, TeXRA uses GraphicsMagick/ImageMagick + Ghostscript for conversion.</p><h2 id="clipboard-images" tabindex="-1">Clipboard Images <a class="header-anchor" href="#clipboard-images" aria-label="Permalink to &quot;Clipboard Images&quot;">​</a></h2><p>Paste images directly into the instruction area:</p><ol><li>Copy any image to clipboard</li><li>Paste with Ctrl/Cmd+V</li><li>Image is saved and referenced as <code>[pasted_timestamp_hash.ext]</code></li><li>Media Files list updates automatically</li></ol><p>Pasted images are stored temporarily and cleaned up after 3 days.</p><h2 id="automatic-figure-extraction" tabindex="-1">Automatic Figure Extraction <a class="header-anchor" href="#automatic-figure-extraction" aria-label="Permalink to &quot;Automatic Figure Extraction&quot;">​</a></h2><p>Enable via the Auto-extract dropdown near the Media label:</p><ul><li><strong>Figures</strong>: Extracts images from <code>\\includegraphics</code> commands</li><li><strong>TikZ Figures</strong>: Extracts <code>tikzpicture</code> environments as <code>.tikz</code> files</li></ul><h2 id="figure-extraction-tools" tabindex="-1">Figure Extraction Tools <a class="header-anchor" href="#figure-extraction-tools" aria-label="Permalink to &quot;Figure Extraction Tools&quot;">​</a></h2><p>Tool-use agents can extract figures programmatically:</p><h3 id="extract-figures" tabindex="-1"><code>extract_figures</code> <a class="header-anchor" href="#extract-figures" aria-label="Permalink to &quot;`extract_figures`&quot;">​</a></h3><p>Scans for <code>\\includegraphics</code> and returns referenced files (max 20 attachments):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;extract_figures&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;texPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paper/main.tex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="extract-tikz-figures" tabindex="-1"><code>extract_tikz_figures</code> <a class="header-anchor" href="#extract-tikz-figures" aria-label="Permalink to &quot;`extract_tikz_figures`&quot;">​</a></h3><p>Extracts and optionally compiles TikZ environments (max 12 PDFs):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;extract_tikz_figures&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;texPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paper/main.tex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;compile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="extract-bib-entries" tabindex="-1"><code>extract_bib_entries</code> <a class="header-anchor" href="#extract-bib-entries" aria-label="Permalink to &quot;`extract_bib_entries`&quot;">​</a></h3><p>Retrieves BibTeX records for citations.</p><h2 id="using-media-files" tabindex="-1">Using Media Files <a class="header-anchor" href="#using-media-files" aria-label="Permalink to &quot;Using Media Files&quot;">​</a></h2><p>When you provide media files:</p><ul><li><strong>Vision models</strong> (GPT-4o, Gemini): Images are encoded and included with the prompt</li><li><strong>Audio models</strong>: Audio files are uploaded for transcription</li><li><strong>Non-multimodal models</strong>: Filenames provide context</li></ul><p>Common use cases:</p><ul><li>Write captions for images (<code>polish</code> agent)</li><li>Verify text matches figures (<code>correct</code> agent)</li><li>Generate text from images/PDFs (<code>ocr</code> agent)</li><li>Transcribe audio (<code>transcribe_audio</code> agent)</li></ul><p>For TikZ-specific workflows, see <a href="./tikz-figures.html">TikZ Figures</a>.</p>',34)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
